import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import Header from "../components/header";
import Footer from "../components/footer";

const Results = () => {
  const location = useLocation();
  const query = location.state?.query;

  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!query) return;

    const fetchData = async () => {
      try {
        const apiKey = process.env.REACT_APP_SERP_API_KEY;

        const response = await fetch(
          `https://serpapi.com/search.json?engine=google&q=${query}+price+Pakistan&api_key=${apiKey}`
        );

        const data = await response.json();

        console.log("FULL API RESPONSE:", data);

        // ✅ FIX: multiple fallback sources
        const results =
          data.shopping_results ||
          data.organic_results ||
          data.inline_shopping_results ||
          [];

        const formatted = results.slice(0, 4).map((item) => ({
          title: item.title,
          price: item.price || "N/A",
          rating: item.rating || "N/A",
          image: item.thumbnail || item.image,
          link: item.link,
          source: item.source || "Unknown",
        }));

        setProducts(formatted);
        setLoading(false);

      } catch (error) {
        console.log("ERROR:", error);
        setLoading(false);
      }
    };

    fetchData();
  }, [query]);

  const addToFavorite = (product) => {
    let fav = JSON.parse(localStorage.getItem("favorites")) || [];
    fav.push(product);
    localStorage.setItem("favorites", JSON.stringify(fav));
    alert("Added to favorites!");
  };

  return (
    <>
      <Header />

      <div style={{ padding: "20px" }}>
        <h2>Results</h2>
        <p>Search: {query}</p>

        {loading ? (
          <p>Loading...</p>
        ) : products.length === 0 ? (
          <p>No products found 😢</p>
        ) : (
          products.map((item, index) => (
            <div key={index} style={{ border: "1px solid #ccc", margin: 10, padding: 10 }}>
              
              <img src={item.image} alt="" width="120" />

              <h3>{item.title}</h3>

              <p>Price: {item.price}</p>
              <p>Rating: {item.rating}</p>
              <p>Source: {item.source}</p>

              <button onClick={() => addToFavorite(item)}>
                Add to Favorite
              </button>

              <a href={item.link} target="_blank" rel="noreferrer">
                <button>Go to Website</button>
              </a>

            </div>
          ))
        )}
      </div>

      <Footer />
    </>
  );
};

export default Results;
